import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose2d_forward(torch::Tensor x,
                                        torch::Tensor w,
                                        c10::optional<torch::Tensor> b,
                                        int stride_h, int stride_w,
                                        int pad_h, int pad_w,
                                        int dil_h, int dil_w,
                                        int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv_transpose2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int IC, int OC, int IH, int IW, int OH, int OW,
    int KH, int KW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups, int Cin_per_group, int Cout_per_group)
{
  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int CcPerBlock = 8;

  const int tid = threadIdx.x;

  const int n      = blockIdx.z;
  const int c_tile = blockIdx.y;
  const int c_base = c_tile * CcPerBlock;

  const int P_total = OH * OW;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // Global tensors via CuTe
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * (int64_t)IC * IH * IW),
      make_shape(IC, IH, IW),
      make_stride((int64_t)IH * IW, (int64_t)IW, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * (int64_t)OC * OH * OW),
      make_shape(OC, OH, OW),
      make_stride((int64_t)OH * OW, (int64_t)OW, Int<1>{})
  );

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(IC, Cout_per_group, KH, KW),
      make_stride((int64_t)Cout_per_group * KH * KW, (int64_t)KH * KW, KW, Int<1>{})
  );

  // Dynamic shared memory: [CcPerBlock][Cin_per_group][KH][KW]
  extern __shared__ float smem[];
  const int per_cc_size = Cin_per_group * KH * KW;

  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    if (c >= OC) continue;
    int group        = c / Cout_per_group;
    int oc_in_group  = c - group * Cout_per_group;
    int ic_base      = group * Cin_per_group;

    for (int idx = tid; idx < per_cc_size; idx += Threads) {
      int kw = idx % KW;
      int tmp = idx / KW;
      int kh = tmp % KH;
      int ic_in_group = tmp / KH;
      int ic = ic_base + ic_in_group;
      float wval = (float)mW(ic, oc_in_group, kh, kw);
      smem[cc * per_cc_size + idx] = wval;
    }
  }
  __syncthreads();

  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      oh_arr[i] = p / OW;
      ow_arr[i] = p - oh_arr[i] * OW;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  float acc[CcPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    float bval = 0.0f;
    if (Bias != nullptr && c < OC) {
      bval = (float)Bias[c];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = bval;
    }
  }

  // Determine whether every output channel handled by this CTA tile
  // belongs to the same group. When true, the input activation value
  // for a given (ic_in_group, ih, iw) is identical across all CcPerBlock
  // output channels, so it can be loaded once from global memory and
  // reused for all of them instead of being re-fetched per channel.
  int c_last_in_block = c_base + CcPerBlock - 1;
  if (c_last_in_block >= OC) c_last_in_block = OC - 1;
  int group0 = (c_base < OC) ? (c_base / Cout_per_group) : 0;
  int group_last = (c_last_in_block >= 0) ? (c_last_in_block / Cout_per_group) : group0;
  bool same_group_block = (c_base < OC) && (group0 == group_last);
  int ic_base_common = group0 * Cin_per_group;
  for (int kh = 0; kh < KH; ++kh) {
    for (int kw = 0; kw < KW; ++kw) {
      // Precompute source coordinates / validity for every output pixel
      // handled by this thread once per (kh, kw); this lets the weight
      // value (constant across pixels) be loaded from shared memory a
      // single time and reused for all PVec pixels instead of being
      // re-read from shared memory for every pixel.
      int ih_arr[PVec], iw_arr[PVec];
      bool valid_arr[PVec];
      #pragma unroll
      for (int i = 0; i < PVec; ++i) {
        valid_arr[i] = false;
        int p = p_idx[i];
        if (p >= P_total) continue;
        int oh = oh_arr[i];
        int ow = ow_arr[i];
        int num_h = oh + pad_h - kh * dil_h;
        if (num_h % stride_h != 0) continue;
        int ih = num_h / stride_h;
        if (ih < 0 || ih >= IH) continue;
        int num_w = ow + pad_w - kw * dil_w;
        if (num_w % stride_w != 0) continue;
        int iw = num_w / stride_w;
        if (iw < 0 || iw >= IW) continue;
        ih_arr[i] = ih;
        iw_arr[i] = iw;
        valid_arr[i] = true;
      }
      if (same_group_block) {
        // Load each input value once and reuse it across every
        // output channel in this CTA tile that shares the group.
        // Additionally, load each weight value from shared memory
        // once per (kh, kw, ic_in_group) into registers and reuse it
        // across every output pixel handled by this thread.
        for (int ic_in_group = 0; ic_in_group < Cin_per_group; ++ic_in_group) {
          int ic = ic_base_common + ic_in_group;
          float wreg[CcPerBlock];
          #pragma unroll
          for (int cc = 0; cc < CcPerBlock; ++cc) {
            wreg[cc] = smem[cc * per_cc_size + (ic_in_group * KH + kh) * KW + kw];
          }
          #pragma unroll
          for (int i = 0; i < PVec; ++i) {
            if (!valid_arr[i]) continue;
            float xval = (float)mX(ic, ih_arr[i], iw_arr[i]);
            #pragma unroll
            for (int cc = 0; cc < CcPerBlock; ++cc) {
              int c = c_base + cc;
              if (c >= OC) continue;
              acc[cc][i] += xval * wreg[cc];
            }
          }
        }
      } else {
        #pragma unroll
        for (int cc = 0; cc < CcPerBlock; ++cc) {
          int c = c_base + cc;
          if (c >= OC) continue;
          int group   = c / Cout_per_group;
          int ic_base = group * Cin_per_group;
          float sum_ic[PVec];
          #pragma unroll
          for (int i = 0; i < PVec; ++i) sum_ic[i] = 0.0f;
          for (int ic_in_group = 0; ic_in_group < Cin_per_group; ++ic_in_group) {
            int ic = ic_base + ic_in_group;
            float wval = smem[cc * per_cc_size + (ic_in_group * KH + kh) * KW + kw];
            #pragma unroll
            for (int i = 0; i < PVec; ++i) {
              if (!valid_arr[i]) continue;
              float xval = (float)mX(ic, ih_arr[i], iw_arr[i]);
              sum_ic[i] += xval * wval;
            }
          }
          #pragma unroll
          for (int i = 0; i < PVec; ++i) acc[cc][i] += sum_ic[i];
        }
      }
    }
  }

  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    if (c >= OC) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(c, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv_transpose2d_forward(torch::Tensor x,
                                        torch::Tensor w,
                                        c10::optional<torch::Tensor> b,
                                        int stride_h, int stride_w,
                                        int pad_h, int pad_w,
                                        int dil_h, int dil_w,
                                        int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [IC, OC/groups, KH, KW]");

  int64_t N   = x.size(0);
  int64_t IC  = x.size(1);
  int64_t IH  = x.size(2);
  int64_t IW  = x.size(3);

  TORCH_CHECK(w.size(0) == IC, "w.size(0) must equal in_channels");
  int64_t Cout_per_group = w.size(1);
  int64_t KH = w.size(2);
  int64_t KW = w.size(3);
  int64_t OC = Cout_per_group * groups;
  int64_t Cin_per_group = IC / groups;

  int64_t OH = (IH - 1) * stride_h - 2 * pad_h + dil_h * (KH - 1) + 1;
  int64_t OW = (IW - 1) * stride_w - 2 * pad_w + dil_w * (KW - 1) + 1;
  TORCH_CHECK(OH > 0 && OW > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, OH, OW}, x.options());

  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int CcPerBlock = 8;

  const int64_t P_total = OH * OW;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((OC + CcPerBlock - 1) / CcPerBlock),
      (unsigned)N
  );

  size_t smem_bytes = (size_t)CcPerBlock * (size_t)Cin_per_group * (size_t)KH * (size_t)KW * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv_transpose2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)IC, (int)OC, (int)IH, (int)IW, (int)OH, (int)OW,
      (int)KH, (int)KW,
      stride_h, stride_w,
      pad_h, pad_w,
      dil_h, dil_w,
      groups, (int)Cin_per_group, (int)Cout_per_group
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
"""

conv_transpose2d_ext = load_inline(
    name="cute_conv_transpose2d_ext",
    cpp_sources=cuda_decl,
    cuda_sources=cuda_src,
    functions=["conv_transpose2d_forward"],
    extra_cflags=["-O3"],
    extra_cuda_cflags=["-O3"],
    extra_include_paths=["/root/cutegen_test/cutegen/cutlass/include"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Grouped, dilated, padded, strided 2D transposed convolution implemented
    with a single custom CUDA/CUTE kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1), padding: tuple = (0, 0),
                 dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = tuple(kernel_size)
        self.stride = tuple(stride)
        self.padding = tuple(padding)
        self.dilation = tuple(dilation)
        self.groups = int(groups)

        assert self.in_channels % self.groups == 0
        assert self.out_channels % self.groups == 0

        KH, KW = self.kernel_size
        Cout_per_group = self.out_channels // self.groups

        # PyTorch ConvTranspose2d weight layout: [in_channels, out_channels/groups, KH, KW]
        self.weight = nn.Parameter(torch.empty(self.in_channels, Cout_per_group, KH, KW))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv_transpose2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            Cin_per_group = self.in_channels // self.groups
            KH, KW = self.kernel_size
            fan_in = Cin_per_group * KH * KW
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        sh, sw = self.stride
        ph, pw = self.padding
        dh, dw = self.dilation
        return self._ext.conv_transpose2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(sh), int(sw),
            int(ph), int(pw),
            int(dh), int(dw),
            int(self.groups),
        )

