import math
import torch
import torch.nn as nn
import torch.nn.init as init
from torch.utils.cpp_extension import load_inline

cuda_decl = r"""
#include <torch/extension.h>
torch::Tensor conv_transpose2d_forward(torch::Tensor x,
                                        torch::Tensor w,
                                        c10::optional<torch::Tensor> b,
                                        int stride_h, int stride_w,
                                        int pad_h, int pad_w,
                                        int dil_h, int dil_w,
                                        int groups);
"""

cuda_src = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <c10/cuda/CUDAStream.h>
#include <cute/tensor.hpp>

using namespace cute;

template <typename T>
__global__ void conv_transpose2d_kernel(
    const T* __restrict__ X,
    const T* __restrict__ W,
    const T* __restrict__ Bias,
    T* __restrict__ Y,
    int N, int IC, int OC, int IH, int IW, int OH, int OW,
    int KH, int KW,
    int stride_h, int stride_w,
    int pad_h, int pad_w,
    int dil_h, int dil_w,
    int groups, int Cin_per_group, int Cout_per_group)
{
  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int CcPerBlock = 8;

  const int tid = threadIdx.x;

  const int n      = blockIdx.z;
  const int c_tile = blockIdx.y;
  const int c_base = c_tile * CcPerBlock;

  const int P_total = OH * OW;
  const int PTile   = Threads * PVec;
  const int p_block = blockIdx.x * PTile;

  // Global tensors via CuTe
  auto mX = make_tensor(
      make_gmem_ptr(X + (int64_t)n * (int64_t)IC * IH * IW),
      make_shape(IC, IH, IW),
      make_stride((int64_t)IH * IW, (int64_t)IW, Int<1>{})
  );

  auto mY = make_tensor(
      make_gmem_ptr(Y + (int64_t)n * (int64_t)OC * OH * OW),
      make_shape(OC, OH, OW),
      make_stride((int64_t)OH * OW, (int64_t)OW, Int<1>{})
  );

  auto mW = make_tensor(
      make_gmem_ptr(W),
      make_shape(IC, Cout_per_group, KH, KW),
      make_stride((int64_t)Cout_per_group * KH * KW, (int64_t)KH * KW, KW, Int<1>{})
  );

  // Dynamic shared memory: [CcPerBlock][Cin_per_group][KH][KW]
  extern __shared__ float smem[];
  const int per_cc_size = Cin_per_group * KH * KW;

  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    if (c >= OC) continue;
    int group        = c / Cout_per_group;
    int oc_in_group  = c - group * Cout_per_group;
    int ic_base      = group * Cin_per_group;

    for (int idx = tid; idx < per_cc_size; idx += Threads) {
      int kw = idx % KW;
      int tmp = idx / KW;
      int kh = tmp % KH;
      int ic_in_group = tmp / KH;
      int ic = ic_base + ic_in_group;
      float wval = (float)mW(ic, oc_in_group, kh, kw);
      smem[cc * per_cc_size + idx] = wval;
    }
  }
  __syncthreads();

  int p_idx[PVec];
  int oh_arr[PVec];
  int ow_arr[PVec];

  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_block + tid + i * Threads;
    p_idx[i] = p;
    if (p < P_total) {
      oh_arr[i] = p / OW;
      ow_arr[i] = p - oh_arr[i] * OW;
    } else {
      oh_arr[i] = 0;
      ow_arr[i] = 0;
    }
  }

  float acc[CcPerBlock][PVec];
  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    float bval = 0.0f;
    if (Bias != nullptr && c < OC) {
      bval = (float)Bias[c];
    }
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      acc[cc][i] = bval;
    }
  }

  // Determine whether every output channel handled by this CTA tile
  // belongs to the same group. When true, the input activation value
  // for a given (ic_in_group, ih, iw) is identical across all CcPerBlock
  // output channels, so it can be loaded once from global memory and
  // reused for all of them instead of being re-fetched per channel.
  int c_last_in_block = c_base + CcPerBlock - 1;
  if (c_last_in_block >= OC) c_last_in_block = OC - 1;
  int group0 = (c_base < OC) ? (c_base / Cout_per_group) : 0;
  int group_last = (c_last_in_block >= 0) ? (c_last_in_block / Cout_per_group) : group0;
  bool same_group_block = (c_base < OC) && (group0 == group_last);
  int ic_base_common = group0 * Cin_per_group;
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_idx[i];
    if (p >= P_total) continue;
    int oh = oh_arr[i];
    int ow = ow_arr[i];
    for (int kh = 0; kh < KH; ++kh) {
      int num_h = oh + pad_h - kh * dil_h;
      if (num_h % stride_h != 0) continue;
      int ih = num_h / stride_h;
      if (ih < 0 || ih >= IH) continue;
      for (int kw = 0; kw < KW; ++kw) {
        int num_w = ow + pad_w - kw * dil_w;
        if (num_w % stride_w != 0) continue;
        int iw = num_w / stride_w;
        if (iw < 0 || iw >= IW) continue;
        if (same_group_block) {
          // Load each input value once and reuse it across every
          // output channel in this CTA tile that shares the group.
          for (int ic_in_group = 0; ic_in_group < Cin_per_group; ++ic_in_group) {
            int ic = ic_base_common + ic_in_group;
            float xval = (float)mX(ic, ih, iw);
            #pragma unroll
            for (int cc = 0; cc < CcPerBlock; ++cc) {
              int c = c_base + cc;
              if (c >= OC) continue;
              float wval = smem[cc * per_cc_size + (ic_in_group * KH + kh) * KW + kw];
              acc[cc][i] += xval * wval;
            }
          }
        } else {
          #pragma unroll
          for (int cc = 0; cc < CcPerBlock; ++cc) {
            int c = c_base + cc;
            if (c >= OC) continue;
            int group   = c / Cout_per_group;
            int ic_base = group * Cin_per_group;
            float sum_ic = 0.0f;
            for (int ic_in_group = 0; ic_in_group < Cin_per_group; ++ic_in_group) {
              int ic = ic_base + ic_in_group;
              float xval = (float)mX(ic, ih, iw);
              float wval = smem[cc * per_cc_size + (ic_in_group * KH + kh) * KW + kw];
              sum_ic += xval * wval;
            }
            acc[cc][i] += sum_ic;
          }
        }
      }
    }
  }

  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    if (c >= OC) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(c, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv_transpose2d_forward(torch::Tensor x,
                                        torch::Tensor w,
                                        c10::optional<torch::Tensor> b,
                                        int stride_h, int stride_w,
                                        int pad_h, int pad_w,
                                        int dil_h, int dil_w,
                                        int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [IC, OC/groups, KH, KW]");

  int64_t N   = x.size(0);
  int64_t IC  = x.size(1);
  int64_t IH  = x.size(2);
  int64_t IW  = x.size(3);

  TORCH_CHECK(w.size(0) == IC, "w.size(0) must equal in_channels");
  int64_t Cout_per_group = w.size(1);
  int64_t KH = w.size(2);
