  // Determine whether every output channel handled by this CTA tile
  // belongs to the same group. When true, the input activation value
  // for a given (ic_in_group, ih, iw) is identical across all CcPerBlock
  // output channels, so it can be loaded once from global memory and
  // reused for all of them instead of being re-fetched per channel.
  int c_last_in_block = c_base + CcPerBlock - 1;
  if (c_last_in_block >= OC) c_last_in_block = OC - 1;
  int group0 = (c_base < OC) ? (c_base / Cout_per_group) : 0;
  int group_last = (c_last_in_block >= 0) ? (c_last_in_block / Cout_per_group) : group0;
  bool same_group_block = (c_base < OC) && (group0 == group_last);
  int ic_base_common = group0 * Cin_per_group;
  #pragma unroll
  for (int i = 0; i < PVec; ++i) {
    int p = p_idx[i];
    if (p >= P_total) continue;
    int oh = oh_arr[i];
    int ow = ow_arr[i];
    for (int kh = 0; kh < KH; ++kh) {
      int num_h = oh + pad_h - kh * dil_h;
      if (num_h % stride_h != 0) continue;
      int ih = num_h / stride_h;
      if (ih < 0 || ih >= IH) continue;
      for (int kw = 0; kw < KW; ++kw) {
        int num_w = ow + pad_w - kw * dil_w;
        if (num_w % stride_w != 0) continue;
        int iw = num_w / stride_w;
        if (iw < 0 || iw >= IW) continue;
        if (same_group_block) {
          // Load each input value once and reuse it across every
          // output channel in this CTA tile that shares the group.
          for (int ic_in_group = 0; ic_in_group < Cin_per_group; ++ic_in_group) {
            int ic = ic_base_common + ic_in_group;
            float xval = (float)mX(ic, ih, iw);
            #pragma unroll
            for (int cc = 0; cc < CcPerBlock; ++cc) {
              int c = c_base + cc;
              if (c >= OC) continue;
              float wval = smem[cc * per_cc_size + (ic_in_group * KH + kh) * KW + kw];
              acc[cc][i] += xval * wval;
            }
          }
        } else {
          #pragma unroll
          for (int cc = 0; cc < CcPerBlock; ++cc) {
            int c = c_base + cc;
            if (c >= OC) continue;
            int group   = c / Cout_per_group;
            int ic_base = group * Cin_per_group;
            float sum_ic = 0.0f;
            for (int ic_in_group = 0; ic_in_group < Cin_per_group; ++ic_in_group) {
              int ic = ic_base + ic_in_group;
              float xval = (float)mX(ic, ih, iw);
              float wval = smem[cc * per_cc_size + (ic_in_group * KH + kh) * KW + kw];
              sum_ic += xval * wval;
            }
            acc[cc][i] += sum_ic;
          }
        }
      }
    }
  }

  #pragma unroll
  for (int cc = 0; cc < CcPerBlock; ++cc) {
    int c = c_base + cc;
    if (c >= OC) continue;
    #pragma unroll
    for (int i = 0; i < PVec; ++i) {
      int p = p_idx[i];
      if (p >= P_total) continue;
      mY(c, oh_arr[i], ow_arr[i]) = static_cast<T>(acc[cc][i]);
    }
  }
}

torch::Tensor conv_transpose2d_forward(torch::Tensor x,
                                        torch::Tensor w,
                                        c10::optional<torch::Tensor> b,
                                        int stride_h, int stride_w,
                                        int pad_h, int pad_w,
                                        int dil_h, int dil_w,
                                        int groups) {
  TORCH_CHECK(x.is_cuda(), "x must be CUDA");
  TORCH_CHECK(w.is_cuda(), "w must be CUDA");
  if (b.has_value()) TORCH_CHECK(b.value().is_cuda(), "bias must be CUDA if provided");

  TORCH_CHECK(x.scalar_type() == at::kFloat, "x must be float32");
  TORCH_CHECK(w.scalar_type() == at::kFloat, "w must be float32");
  if (b.has_value()) TORCH_CHECK(b.value().scalar_type() == at::kFloat, "bias must be float32");

  TORCH_CHECK(x.dim() == 4, "x must be [N, C, H, W]");
  TORCH_CHECK(w.dim() == 4, "w must be [IC, OC/groups, KH, KW]");

  int64_t N   = x.size(0);
  int64_t IC  = x.size(1);
  int64_t IH  = x.size(2);
  int64_t IW  = x.size(3);

  TORCH_CHECK(w.size(0) == IC, "w.size(0) must equal in_channels");
  int64_t Cout_per_group = w.size(1);
  int64_t KH = w.size(2);
  int64_t KW = w.size(3);
  int64_t OC = Cout_per_group * groups;
  int64_t Cin_per_group = IC / groups;

  int64_t OH = (IH - 1) * stride_h - 2 * pad_h + dil_h * (KH - 1) + 1;
  int64_t OW = (IW - 1) * stride_w - 2 * pad_w + dil_w * (KW - 1) + 1;
  TORCH_CHECK(OH > 0 && OW > 0, "Invalid output size computed");

  auto x_c = x.contiguous();
  auto w_c = w.contiguous();

  torch::Tensor b_c;
  const float* b_ptr = nullptr;
  if (b.has_value()) {
    b_c = b.value().contiguous();
    TORCH_CHECK(b_c.dim() == 1 && b_c.size(0) == OC, "bias must be [OC]");
    b_ptr = b_c.data_ptr<float>();
  }

  auto y = torch::empty({N, OC, OH, OW}, x.options());

  constexpr int Threads    = 128;
  constexpr int PVec       = 2;
  constexpr int CcPerBlock = 8;

  const int64_t P_total = OH * OW;
  const int64_t PTile   = Threads * PVec;

  dim3 block(Threads);
  dim3 grid(
      (unsigned)((P_total + PTile - 1) / PTile),
      (unsigned)((OC + CcPerBlock - 1) / CcPerBlock),
      (unsigned)N
  );

  size_t smem_bytes = (size_t)CcPerBlock * (size_t)Cin_per_group * (size_t)KH * (size_t)KW * sizeof(float);

  cudaStream_t stream = c10::cuda::getCurrentCUDAStream().stream();

  conv_transpose2d_kernel<float><<<grid, block, smem_bytes, stream>>>(
      x_c.data_ptr<float>(),
      w_c.data_ptr<float>(),
      b_ptr,
      y.data_ptr<float>(),
      (int)N, (int)IC, (int)OC, (int)IH, (int)IW, (int)OH, (int)OW,
      (int)KH, (int)KW,
      stride_h, stride_w,
      pad_h, pad_w,
      dil_h, dil_w,
      groups, (int)Cin_per_group, (int)Cout_per_group
  );

  auto err = cudaGetLastError();
  TORCH_CHECK(err == cudaSuccess, "conv_transpose2d_kernel launch failed: ", cudaGetErrorString(err));

  return y;
}
