class ModelNew(nn.Module):
    """
    Grouped, dilated, padded, strided 2D transposed convolution implemented
    with a single custom CUDA/CUTE kernel.
    """
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1), padding: tuple = (0, 0),
                 dilation: tuple = (1, 1), groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = int(in_channels)
        self.out_channels = int(out_channels)
        self.kernel_size = tuple(kernel_size)
        self.stride = tuple(stride)
        self.padding = tuple(padding)
        self.dilation = tuple(dilation)
        self.groups = int(groups)

        assert self.in_channels % self.groups == 0
        assert self.out_channels % self.groups == 0

        KH, KW = self.kernel_size
        Cout_per_group = self.out_channels // self.groups

        # PyTorch ConvTranspose2d weight layout: [in_channels, out_channels/groups, KH, KW]
        self.weight = nn.Parameter(torch.empty(self.in_channels, Cout_per_group, KH, KW))
        if bias:
            self.bias = nn.Parameter(torch.empty(self.out_channels))
        else:
            self.register_parameter("bias", None)

        self.reset_parameters()
        self._ext = conv_transpose2d_ext

    def reset_parameters(self):
        init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        if self.bias is not None:
            Cin_per_group = self.in_channels // self.groups
            KH, KW = self.kernel_size
            fan_in = Cin_per_group * KH * KW
            bound = 1.0 / math.sqrt(fan_in) if fan_in > 0 else 0.0
            init.uniform_(self.bias, -bound, bound)

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        sh, sw = self.stride
        ph, pw = self.padding
        dh, dw = self.dilation
        return self._ext.conv_transpose2d_forward(
            x.contiguous(),
            self.weight.contiguous(),
            self.bias if self.bias is not None else None,
            int(sh), int(sw),
            int(ph), int(pw),
            int(dh), int(dw),
            int(self.groups),
        )
